def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1

    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1

        if n == 2:
            results.append("NO")
        elif n == 4:
            results.append("YES")
            results.append("2 4 1 5")
        else:
            if n % 4 != 0:
                results.append("NO")
            else:
                results.append("YES")
                even_numbers = [2 * i for i in range(1, n // 2 + 1)]
                odd_numbers = [2 * i - 1 for i in range(1, n // 2 + 1)]

                # Ensure the sum of even numbers equals the sum of odd numbers
                while sum(even_numbers) != sum(odd_numbers):
                    even_numbers[-1] += 2
                    odd_numbers[-1] += 2

                results.extend(even_numbers)
                results.extend(odd_numbers)

    for result in results:
        print(result)

if __name__ == "__main__":
    solve()
